steps.script:
var mgr = SecondaryMissionManager
var p = GameState.get_active_player()
var opp = 2 if p == 1 else 1
Engine.set_meta("eoaf_player", p)
GameState.state["meta"]["game_config"]["player1_type"] = "HUMAN"
GameState.state["meta"]["game_config"]["player2_type"] = "HUMAN"
for k in [p, opp]:
	if not mgr.is_initialized(k):
		mgr.setup_tactical_deck(k)
	mgr._player_state[str(k)]["mode"] = "tactical"
	mgr._player_state[str(k)]["active"] = []
var st = mgr._player_state[str(p)]
for mid in ["burden_of_trust", "engage_on_all_fronts"]:
	st["active"].append(mgr._create_active_mission(SecondaryMissionData.get_mission_by_id(mid)))
var bw = Measurement.inches_to_px(44.0)
var bh = Measurement.inches_to_px(60.0)
var spots = [Vector2(bw * 0.2, bh * 0.2), Vector2(bw * 0.7, bh * 0.2), Vector2(bw * 0.2, bh * 0.7)]
var placed = 0
for uid in GameState.state["units"].keys():
	var u = GameState.state["units"][uid]
	var models = u.get("models", [])
	if models.size() == 0 or int(u.get("owner", 0)) != p:
		continue
	if placed >= spots.size():
		for m in models:
			m["alive"] = false
		continue
	var c = spots[placed]
	var mi = 0
	for m in models:
		m["position"] = {"x": c.x + Measurement.inches_to_px((mi % 3) * 1.4), "y": c.y + Measurement.inches_to_px(int(mi / 3) * 1.4)}
		mi += 1
	placed += 1
return "placed=%d quarters=%s" % [placed, str(AIDecisionMaker._get_covered_quarters(GameState.state["units"], p))]

var d = AIPlayer.request_suggestion()
var types = []
for r in d.get("_ai_decision_records", []):
	types.append(str(r.get("decision_type", "")))
return "%s|%s|%s" % [d.get("type", ""), d.get("_ai_description", ""), str("secondary_score" in types)]

# A unit straddling the vertical halfway line is NOT wholly within a quarter
var p = int(Engine.get_meta("eoaf_player"))
var mid_x = Measurement.inches_to_px(22.0)
for uid in GameState.state["units"].keys():
	var u = GameState.state["units"][uid]
	if int(u.get("owner", 0)) != p:
		continue
	var first = u["models"][0]["position"]
	if first["x"] > mid_x:
		var mi = 0
		for m in u["models"]:
			m["position"]["x"] = mid_x - Measurement.inches_to_px(1.5) + Measurement.inches_to_px((mi % 3) * 1.4)
			mi += 1
return str(AIDecisionMaker._get_covered_quarters(GameState.state["units"], p))
